// Smooth closed/open curve through points (Catmull-Rom to cubic Bezier).
// A point written [x, y, 'c'] is a hard corner.
function spline(pts, closed = true) {
  const P = pts.map((p) => ({ x: p[0], y: p[1], c: p[2] === 'c' }));
  const m = P.length;
  const segs = closed ? m : m - 1;
  let d = `M${f(P[0].x)} ${f(P[0].y)}`;
  for (let i = 0; i < segs; i++) {
    const p1 = P[i];
    const p2 = P[(i + 1) % m];
    const p0 = !closed && i === 0 ? p1 : P[(i - 1 + m) % m];
    const p3 = !closed && i === segs - 1 ? p2 : P[(i + 2) % m];
    const c1 = p1.c ? p1 : { x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6 };
    const c2 = p2.c ? p2 : { x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6 };
    d += `C${f(c1.x)} ${f(c1.y)} ${f(c2.x)} ${f(c2.y)} ${f(p2.x)} ${f(p2.y)}`;
  }
  return d + (closed ? 'Z' : '');
}

// The same curve sampled to a polygon, and a point-in-polygon test for it.
function splinePoly(pts, steps = 6) {
  const P = pts.map((p) => ({ x: p[0], y: p[1], c: p[2] === 'c' }));
  const m = P.length;
  const out = [];
  for (let i = 0; i < m; i++) {
    const p0 = P[(i - 1 + m) % m], p1 = P[i], p2 = P[(i + 1) % m], p3 = P[(i + 2) % m];
    const c1 = p1.c ? p1 : { x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6 };
    const c2 = p2.c ? p2 : { x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6 };
    for (let s = 0; s < steps; s++) {
      const t = s / steps, u = 1 - t;
      out.push([u * u * u * p1.x + 3 * u * u * t * c1.x + 3 * u * t * t * c2.x + t * t * t * p2.x,
        u * u * u * p1.y + 3 * u * u * t * c1.y + 3 * u * t * t * c2.y + t * t * t * p2.y]);
    }
  }
  return out;
}
function inPoly(poly, x, y) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i], [xj, yj] = poly[j];
    if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

// Lit cells of a boolean grid as one compact path: horizontal runs, merged
// down rows when the run repeats.
function cellsPath(rows, on = (v) => v) {
  const rects = [];
  let active = new Map();
  rows.forEach((row, y) => {
    const next = new Map();
    let x = 0;
    while (x < row.length) {
      if (!on(row[x])) { x++; continue; }
      let x1 = x;
      while (x1 < row.length && on(row[x1])) x1++;
      const key = `${x},${x1}`;
      const r = active.get(key);
      if (r) { r.h++; next.set(key, r); } else { const nr = { x, y, w: x1 - x, h: 1 }; rects.push(nr); next.set(key, nr); }
      x = x1;
    }
    active = next;
  });
  return rects.map((r) => `M${r.x} ${r.y}h${r.w}v${r.h}h${-r.w}z`).join('');
}
// A grid of colour strings ('' = empty) as one <path> per colour.
function gridSvg(grid) {
  const colours = [...new Set(grid.flat())].filter(Boolean);
  return colours.map((c) => `<path fill="${c}" d="${cellsPath(grid, (v) => v === c)}"/>`).join('');
}

