// Two-ring bevel: [outer top-left, outer bottom-right, inner top-left, inner bottom-right].
function bevel(x, y, w, h, [a, b, c, d]) {
  const ring = (ix, iy, iw, ih, tl, br) => (tl ? px(tl, R(ix, iy, iw - 1, 1) + R(ix, iy + 1, 1, ih - 2)) : '')
    + (br ? px(br, R(ix, iy + ih - 1, iw, 1) + R(ix + iw - 1, iy, 1, ih - 1)) : '');
  return ring(x, y, w, h, a, b) + (c || d ? ring(x + 1, y + 1, w - 2, h - 2, c, d) : '');
}
const RAISED_WIN = [LITE, DARK, WHITE, GREY];
const RAISED_BTN = [WHITE, DARK, LITE, GREY];
const SUNKEN = [GREY, WHITE, DARK, LITE];
const STATUS = [GREY, WHITE, null, null];
function button(x, y, w, h, label, { bold = false, focus = false } = {}) {
  let s = box(FACE, x, y, w, h) + bevel(x, y, w, h, RAISED_BTN);
  if (focus) s = box(DARK, x - 1, y - 1, w + 2, h + 2) + s;
  s += text(label, x + Math.round(w / 2), y + Math.round((h - 7) / 2), '#000', { bold, align: 'center' });
  return s;
}
function captionButton(x, y, kind) {
  const glyph = {
    x: 'M4 3h2v1h1v1h2v-1h1v-1h2v1h-1v1h-1v1h-1v1h1v1h1v1h1v1h-2v-1h-1v-1h-2v1h-1v1h-2v-1h1v-1h1v-1h1v-1h-1v-1h-1v-1h-1z',
    q: 'M6 3h4v1h1v2h-1v1h-1v1h-2v-1h1v-1h1v-2h-2v1h-2v-1h1zM7 9h2v2h-2z',
    min: 'M4 9h6v2h-6z',
    max: 'M3 2h9v9h-9zM4 4v6h7v-6z',
  }[kind];
  return box(FACE, x, y, 16, 14) + bevel(x, y, 16, 14, RAISED_BTN) + `<path transform="translate(${x} ${y})" d="${glyph}"/>`;
}
function windowFrame(w, h, title, { icon = '', buttons = ['x'], active = true } = {}) {
  let s = box(FACE, 0, 0, w, h) + bevel(0, 0, w, h, RAISED_WIN);
  s += box(active ? NAVY : GREY, 3, 3, w - 6, 18);
  let tx = 6;
  if (icon) { s += `<g transform="translate(5 4)">${icon}</g>`; tx = 24; }
  s += text(title, tx, 8, active ? WHITE : FACE, { bold: true });
  let bx = w - 5 - 16;
  for (const b of buttons) { s += captionButton(bx, 5, b); bx -= b === 'x' ? 18 : 16; }
  return s;
}

// The app's emblem, a hexagon with a cog inside, rasterised to a pixel icon.
function emblemIcon(size) {
  const grid = [];
  const c = size / 2;
  const Rh = size * 0.47;
  for (let y = 0; y < size; y++) {
    const row = [];
    for (let x = 0; x < size; x++) {
      const dx = x + 0.5 - c;
      const dy = y + 0.5 - c;
      // Distance to a hexagon with its points at top and bottom.
      const hex = Math.max(Math.abs(dx), Math.abs(dx) * 0.5 + Math.abs(dy) * 0.8660254);
      const r = Math.hypot(dx, dy);
      const a = Math.atan2(dy, dx);
      const tooth = Math.cos(a * 8) > 0.15;
      const cogR = size * (tooth ? 0.3 : 0.22);
      let v = '';
      if (hex <= Rh) v = '#0b0b16';
      if (hex <= Rh && hex > Rh - Math.max(1.2, size * 0.075)) v = CYAN;
      if (r <= cogR && r > size * 0.095) v = GOLD;
      row.push(v);
    }
    grid.push(row);
  }
  return gridSvg(grid);
}

