  const kf = (name, spans) => `@keyframes ${name}{0%{opacity:${spans[0][0] === 0 ? 1 : 0}}${spans.map(([on, off]) => `${on ? `${pct(on)}{opacity:1}` : ''}${off < LOOP ? `${pct(off)}{opacity:0}` : ''}`).join('')}100%{opacity:${spans[spans.length - 1][1] >= LOOP ? 1 : 0}}}`;
  const step = (i) => kf(`p${i}`, i === 0 ? [[0, T_TAB[1]], [T_TAB[0], LOOP]] : [[T_TAB[i], i === 2 ? T_TAB[0] : T_TAB[i + 1]]]);
  css.push(`.pg{animation:p0 ${LOOP}s step-end infinite}.p1,.p2{opacity:0}.p1{animation-name:p1}.p2{animation-name:p2}${[0, 1, 2].map(step).join('')}`);
