// ---- window B: the pasted picture. A small skyline over water, drawn cell
// by cell, that fades from sunset to night and back while the lights stay on.
const UB = 1.3;
const B = { x: 652, y: 128, w: 176, h: 116 };
const PIC = { w: 81, h: 41, hor: 27 };
function picture(night) {
  const g = Array.from({ length: PIC.h }, () => Array(PIC.w).fill(''));
  const bands = (list, y, x) => {
    let b = 0;
    while (b + 1 < list.length && list[b + 1][0] <= y) b++;
    return b > 0 && y === list[b][0] && (x + y) % 2 === 0 ? list[b - 1][1] : list[b][1];
  };
  const sky = night
    ? [[0, '#0d0b3a'], [9, '#1a1560'], [17, '#2f1f80'], [23, '#4a2a96']]
    : [[0, '#3f2b8c'], [5, '#6b3fa6'], [10, '#a44fb0'], [15, '#e0609a'], [20, '#ff8f5e'], [24, '#ffc861']];
  const sea = night
    ? [[27, '#1a1560'], [31, '#120f48'], [36, '#0d0b3a']]
    : [[27, '#8a4aa8'], [31, '#5f3b9a'], [36, '#3f2b8c']];
  for (let y = 0; y < PIC.h; y++) for (let x = 0; x < PIC.w; x++) g[y][x] = bands(y < PIC.hor ? sky : sea, y, x);
  const rw = mulberry32(night ? 0x90d : 0x5ea);
  if (night) {
    for (let i = 0; i < 40; i++) g[Math.floor(rw() * 22)][Math.floor(rw() * PIC.w)] = rw() < 0.5 ? '#ffffff' : '#a9a2ff';
    for (let y = 3; y < 15; y++) for (let x = 52; x < 68; x++) {
      if (Math.hypot(x + 0.5 - 60, y + 0.5 - 9) < 4.3 && Math.hypot(x + 0.5 - 58, y + 0.5 - 8) >= 3.9) g[y][x] = '#f4f0ff';
    }
  } else {
    for (let y = 14; y < PIC.hor; y++) for (let x = 44; x < 70; x++) {
      if (Math.hypot(x + 0.5 - 57, y + 0.5 - 27) < 9.6) g[y][x] = '#fff3b0';
    }
  }
  // light on the water, and a few stray glints
  const lx = night ? 60 : 57;
  for (let y = PIC.hor + 1; y < PIC.h; y++) {
    if (rw() < 0.22) continue;
    const w = (night ? 1 : 3) + Math.floor(rw() * (night ? 4 : 9));
    const x0 = lx - Math.floor(w / 2) + Math.floor(rw() * 3) - 1;
    for (let x = x0; x < x0 + w; x++) g[y][x] = night ? '#cfc8ff' : y < 32 ? '#ffc861' : '#ff8f5e';
  }
  for (let i = 0; i < 16; i++) {
    const y = PIC.hor + 1 + Math.floor(rw() * (PIC.h - PIC.hor - 1));
    const x0 = Math.floor(rw() * (PIC.w - 5));
    const w = 2 + Math.floor(rw() * 3);
    for (let x = x0; x < x0 + w; x++) g[y][x] = night ? '#2f1f80' : '#c77bd0';
  }
  // the skyline: sheds with saw-tooth roofs, stacks, and one very tall mast
  // with a line going straight up out of the frame
  const dark = night ? '#08061c' : '#241545';
  const rs = mulberry32(0xfac7);
  const blocks = [[0, 7, 5], [7, 5, 8], [12, 4, 4], [26, 4, 3], [30, 6, 9], [36, 5, 5], [41, 8, 4, 1], [49, 3, 6], [52, 5, 2],
    [57, 6, 3, 1], [63, 4, 2], [67, 6, 7], [73, 8, 5, 1]];
  for (const [x0, w, h, saw] of blocks) {
    for (let x = x0; x < Math.min(PIC.w, x0 + w); x++) {
      const top = PIC.hor - h - (saw ? 2 - ((x - x0) % 3) : 0);
      for (let y = top; y < PIC.hor; y++) {
        const lit = rs() < (night ? 0.17 : 0.05) && y > top && y < PIC.hor - 1 && x > x0 && x < x0 + w - 1;
        g[y][x] = lit ? '#ffe27a' : dark;
      }
    }
  }
  for (const [x, h] of [[9, 14], [11, 12], [32, 15], [34, 13], [69, 12]]) for (let y = PIC.hor - h; y < PIC.hor; y++) g[y][x] = dark;
  for (const [x, y] of [[10, 12], [11, 11], [12, 11], [13, 10], [14, 10], [33, 11], [34, 10], [35, 10], [36, 9], [37, 9], [38, 8], [70, 14], [71, 13], [72, 13]]) {
    g[y][x] = night ? '#2f1f80' : '#c58bd0';
  }
  for (let y = 0; y < PIC.hor; y++) {
    const half = y < 6 ? 0 : y < 20 ? 1 : y < 23 ? 2 : 3;
    for (let x = 20 - half; x <= 20 + half + (y < 6 ? 0 : 1); x++) g[y][x] = dark;
  }
  for (let x = 17; x <= 24; x++) g[12][x] = dark;
  if (night) { g[6][20] = '#ff5470'; g[11][17] = '#ff5470'; g[11][24] = '#ff5470'; }
  // shore line
  for (let x = 0; x < PIC.w; x++) if ((x * 7) % 5 < 3) g[PIC.hor][x] = dark;
  return gridSvg(g);
}
let winB = '';
{
  winB += box(TEAL, 5, 5, B.w, B.h);
  winB += windowFrame(B.w, B.h, 'overtime.bmp', { buttons: ['x', 'max', 'min'], active: false });
  winB += bevel(5, 24, B.w - 10, PIC.h * 2 + 4, SUNKEN);
  winB += `<g transform="translate(7 26) scale(2)">${picture(false)}<g class="ni">${picture(true)}</g></g>`;
  css.push(`.ni{opacity:0;animation:ni ${LOOP}s linear infinite}@keyframes ni{0%,33%{opacity:0}46%,84%{opacity:1}97%,100%{opacity:0}}`);
}

// ---- dialog C: opens late in the loop with a repaint trail, like dragging
// a window on a machine that is thinking about something else.
const UC = 1.25;
const C = { x: 652, y: 362, w: 188, h: 80 };
const YES = { x: 40, y: 56, w: 52, h: 18 };
let dialog = '';
{
  const tri = [];
  for (let y = 0; y < 28; y++) {
    const row = [];
    const hw = Math.round(y * 0.56) + 1;
    for (let x = 0; x < 33; x++) {
      const d = Math.abs(x - 16);
      let v = '';
      if (d <= hw) v = d >= hw - 1 || y >= 26 || y === 0 ? '#0a0a0a' : '#ffd800';
      if (d <= 1 && ((y >= 9 && y <= 18) || (y >= 21 && y <= 23))) v = '#0a0a0a';
      row.push(v);
    }
    tri.push(row);
  }
  dialog += box(TEAL, 5, 5, C.w, C.h);
  dialog += windowFrame(C.w, C.h, 'screws.exe', { buttons: ['x'] });
  dialog += `<g transform="translate(10 27)">${gridSvg(tri)}</g>`;
  dialog += text('Storage is full of Screws.', 52, 31) + text('Make more Screws?', 52, 43);
  dialog += button(YES.x, YES.y, YES.w, YES.h, 'Yes', { focus: true }) + button(YES.x + YES.w + 8, YES.y, YES.w, YES.h, 'Yes');
  defs.push(`<g id="dlg">${dialog}</g>`);
}
let dialogSvg = '';
{
  const GHOSTS = 4;
  for (let i = 0; i <= GHOSTS; i++) {
    const k = GHOSTS - i;
    dialogSvg += `<g transform="translate(${C.x - k * 6} ${C.y - k * 8}) scale(${UC})"><use href="#dlg" class="tr t${i}"/></g>`;
    css.push(`.t${i}{animation-name:t${i}}@keyframes t${i}{0%{opacity:0}${pct(T_OPEN + i * 0.09)}{opacity:1}${pct(T_CLOSE)}{opacity:0}100%{opacity:0}}`);
  }
  css.unshift(`.tr{opacity:0;animation:t0 ${LOOP}s step-end infinite}`);
}

// ---- the pointer: clicks each tab in turn, then answers the dialog.
let pointer = '';
{
  const tabAt = (i) => [A.x + U * (tabGeom[i].x + tabGeom[i].w - 7), A.y + U * (TAB_Y + 5)];
  const yesAt = [C.x + UC * (YES.x + YES.w * 0.8), C.y + UC * (YES.y + 11)];
  const at = ([x, y]) => `{transform:translate(${f(x)}px,${f(y)}px)}`;
  const rest = [A.x + U * 118, A.y + U * A.h + 22];
  // Arrive 0.4 s before a click, leave 0.35 s after it.
  const visit = (t, p, from = 1.9) => [[t - from, rest], [t - 0.4, p], [t + 0.35, p], [t + 1.5, rest]];
  const frames = [
    [0, rest], ...visit(T_TAB[1], tabAt(1)), ...visit(T_TAB[2], tabAt(2)),
    [T_CLOSE - 2.6, rest], [T_CLOSE - 0.5, yesAt], [T_CLOSE + 0.35, yesAt],
    [T_TAB[0] - 0.4, tabAt(0)], [T_TAB[0] + 0.35, tabAt(0)], [LOOP, rest],
  ];
  frames.forEach(([t], i) => { if (i && t <= frames[i - 1][0]) throw new Error('pointer timeline out of order'); });
  css.push(`.ptr{transform:translate(${f(rest[0])}px,${f(rest[1])}px);animation:ptr ${LOOP}s ease-in-out infinite}@keyframes ptr{${frames.map(([t, p]) => `${pct(t)}${at(p)}`).join('')}}`);
  pointer = `<g class="ptr"><path transform="scale(${U})" d="M0 0V16L4 12.5L7 19L9.5 18L6.5 11.5H11.5Z" fill="#fff" stroke="#000" stroke-width="1" stroke-linejoin="miter"/></g>`;
}

parts.push(`<g transform="translate(${B.x} ${B.y}) scale(${UB})">${winB}</g>`);
parts.push(`<g transform="translate(${A.x} ${A.y}) scale(${U})">${winA}</g>`);
parts.push(dialogSvg);
parts.push(pointer);

// ---------------------------------------------------------------- tears
// Tape damage, rationed: three times a loop a thin slice of the whole picture
// slips sideways for about a tenth of a second. Each slice is a clipped,
// shifted <use> of the scene that is otherwise invisible.
let tears = '';
{
  const TEARS = [[3.1, 203, 7, -20], [3.1, 214, 3, 12], [10.4, 58, 9, 16], [18.4, 318, 12, -26]];
  TEARS.forEach(([t, y, h, dx], i) => {
    defs.push(`<clipPath id="tc${i}"><rect y="${y}" width="${W}" height="${h}"/></clipPath>`);
    tears += `<g clip-path="url(#tc${i})"><rect y="${y}" width="${W}" height="${h}" fill="${PINK}" class="te e${i}"/><use href="#sc" x="${dx}" class="te e${i}"/></g>`;
    css.push(`.e${i}{animation-name:e${i}}@keyframes e${i}{0%{opacity:0}${pct(t)}{opacity:1}${pct(t + 0.12)}{opacity:0}100%{opacity:0}}`);
  });
  css.unshift(`.te{opacity:0;animation:e0 ${LOOP}s step-end infinite}`);
}

// ---------------------------------------------------------------- assemble
const capDefs = [...usedCaps].map((ch) => `<path id="c${ch}" d="${CAPS[ch]}"/>`).join('');
const kanaDefs = [...usedKana].map((ch) => `<path id="k${ch.codePointAt(0).toString(36)}" d="${KANA[ch]}"/>`).join('');
css.push('@media (prefers-reduced-motion:reduce){*{animation-play-state:paused!important}}');

const desc = 'A vaporwave collage banner in the manner of early-2010s album art, for ULTRA-SATISFACTORY, a companion app for the factory game Satisfactory. '
  + 'On a flat hot-pink ground, a white marble bust of a laurel-crowned head in profile stands on a plain block carved VLTRA MMXXVI. '
  + 'At the top right the title ULTRA SATISFACTORY is set in wide-tracked mint capitals over a thin rule, with the Japanese line '
